export function computeEnvelopeValue(startValue, toValue, endValue, rampIn, hold, rampOut, elapsed) {
  const inTicks = durationTicks(rampIn);
  const holdTicks = durationTicks(hold);
  const outTicks = durationTicks(rampOut);

