 */
const META_BY_KEY = (() => {
  const map = new Map();
  for (let i = 0; i < EFFECT_DEFS.length; i++) {
    const def = EFFECT_DEFS[i];
    const familyKey = normalizeKey(def?.id);
    const operation = String(def?.operation || "none").toLowerCase();
