import { ActiveEffects } from "../components/ActiveEffects.js";
import { Faction } from "../components/Faction.js";
import { Position } from "../components/Position.js";
import { Status } from "../components/Status.js";
import { StatusEffectNode } from "../components/StatusEffectNode.js";
import { Vitality } from "../components/Vitality.js";
import { combatSeed, hashString32, mulberry32 } from "./rng.js";
import { forEachInRadius } from "./spatialIndex.js";
import { descendantsWith } from "./topology.js";

const MEMORY_TAMPER_TAGS = new Set([
  "deliriant",
  "delirium",
  "memory_tamper",
  "memory:tamper",
  "memory_tampered",
]);
const MEMORY_IMPAIR_STATUS_KEYS = new Set([
  "confused",
  "hallucinating",
  "mindwiped",
]);
const SOCIAL_FACTIONS = new Set(["player", "shopkeeper", "townfolk", "neutral"]);
const MISATTRIBUTION_RADIUS = 12;

function normId(value) {
  return Number(value || 0) | 0;
}

function addTags(out, source) {
  if (!source || typeof source !== "object") return;
  if (source.type) out.add(String(source.type || "").toLowerCase());
  if (source.key) out.add(String(source.key || "").toLowerCase());
  if (Array.isArray(source.tags)) {
    for (const tag of source.tags) out.add(String(tag || "").toLowerCase());
  }
}

export function socialMemoryTags(world, entityId) {
  const id = normId(entityId);
  const out = new Set();
  const status = world.get(id, Status);
  if (Array.isArray(status?.statuses)) {
    for (const rec of status.statuses) addTags(out, rec);
  }
  const effects = world.get(id, ActiveEffects);
  if (Array.isArray(effects?.effects)) {
    for (const rec of effects.effects) addTags(out, rec);
  }
  for (const [, node] of descendantsWith(world, id, StatusEffectNode)) {
    addTags(out, node);
  }
  return out;
}

export function socialMemoryImpairment(world, entityId) {
  const tags = socialMemoryTags(world, entityId);
  let deliriant = false;
  let impaired = false;
  for (const tag of tags) {
    if (MEMORY_TAMPER_TAGS.has(tag)) {
      deliriant = true;
      impaired = true;
    }
    if (MEMORY_IMPAIR_STATUS_KEYS.has(tag)) impaired = true;
  }
  return { impaired, deliriant, tags };
}

function isPlausibleMisattributionTarget(world, id, excluded) {
  const eid = normId(id);
  if (!(eid > 0) || excluded.has(eid)) return false;
  const fac = String(world.get(eid, Faction)?.key || "").trim().toLowerCase();
  if (!SOCIAL_FACTIONS.has(fac)) return false;
  const vit = world.get(eid, Vitality);
  return !vit || Number(vit.hp || 0) > 0;
}

function pickMisattributionTarget(world, subjectId, actualActorId, victimId, salt) {
  const subject = normId(subjectId);
  const actor = normId(actualActorId);
  const victim = normId(victimId);
  const at = world.get(victim, Position) || world.get(subject, Position) || world.get(actor, Position);
  if (!at) return 0;
  const excluded = new Set([subject, actor, victim]);
  const candidates = [];
  forEachInRadius(world, at.x | 0, at.y | 0, MISATTRIBUTION_RADIUS, (id) => {
    if (isPlausibleMisattributionTarget(world, id, excluded)) candidates.push(id | 0);
  });
  candidates.sort((a, b) => a - b);
  if (candidates.length <= 0) return 0;
  const rng = mulberry32(combatSeed(world.seed >>> 0, world.step | 0, subject, actor, salt >>> 0));
  return candidates[(rng() * candidates.length) | 0] | 0;
}

export function resolveSocialMemoryIntake(world, spec = {}) {
  const subjectId = normId(spec.subjectId);
  const actorId = normId(spec.actorId);
  const victimId = normId(spec.victimId);
  const role = String(spec.role || "witness");
  const impairment = socialMemoryImpairment(world, subjectId);
  if (!impairment.impaired) {
    return {
      subjectId,
      actorId,
      rememberedActorId: actorId,
      outcome: "accurate",
      tags: Object.freeze([...impairment.tags]),
    };
  }

  const tagSalt = hashString32([...impairment.tags].sort().join("|") || "memory");
  const roleSalt = hashString32(role);
  const rng = mulberry32(combatSeed(world.seed >>> 0, world.step | 0, subjectId, actorId, tagSalt ^ roleSalt));
  const roll = rng();
  const dropChance = impairment.deliriant ? 0.45 : 0.25;
  const misrememberChance = impairment.deliriant ? 0.45 : 0.25;
  if (roll < dropChance) {
    return {
      subjectId,
      actorId,
      rememberedActorId: 0,
      outcome: "dropped",
      tags: Object.freeze([...impairment.tags]),
    };
  }

  if (roll < dropChance + misrememberChance) {
    const rememberedActorId = pickMisattributionTarget(world, subjectId, actorId, victimId, tagSalt ^ 0x5A71A11);
    if (rememberedActorId > 0) {
      return {
        subjectId,
        actorId,
        rememberedActorId,
        outcome: "misattributed",
        tags: Object.freeze([...impairment.tags]),
      };
    }
  }

  return {
    subjectId,
    actorId,
    rememberedActorId: actorId,
    outcome: "accurate",
    tags: Object.freeze([...impairment.tags]),
  };
}

